  "marker": "TASK_COMPLETE",
  "answer": {
    "summary": "Apple shows 13 revenue rows for FY2022 because the data includes revenue facts for the annual FY period and for Q1‑Q3 of that year (no Q4 yet), and each of those periods appears multiple times due to ingestion duplication—some rows lack a period_frame while others have a period_frame value.",
    "claims": [
      {
        "text": "For Apple FY2022 there are 3 FY revenue rows, 2 Q1 rows, 4 Q2 rows, and 4 Q3 rows (total 13).",
        "evidence": ["E-7abe3b"]
      },
      {
        "text": "Within each fiscal period, some rows have period_frame NULL and others have a period_frame value (e.g., FY: 2 NULL, 1 CY2020; Q1: 1 NULL, 1 CY2020Q4; Q2: 3 NULL, 1 CY2021Q1; Q3: 3 NULL, 1 CY2021Q2).",
        "evidence": ["E-bff301"]
      },
      {
        "text": "No Q4 revenue rows for FY2022 are present in the data.",
        "evidence": ["E-7abe3b"]
      }
    ],
    "inferences": [
      {
        "text": "The multiple rows per period likely stem from ingestion duplication where the same fact is loaded from both daily and weekly snapshots, yielding rows with and without a period_frame.",
        "basis": ["Claim 2"]
      },
      {
        "text": "The presence of both annual and quarterly revenue facts reflects normal XBRL reporting of interim and annual periods, not an error.",
        "basis": ["Claim 1", "Claim 3"]
      }
    ],
    "hypothesis_verdicts": [
      {
        "id": "H-ab018a",
        "status": "refuted",
        "evidence": ["E-18d446"],
        "why": "Only one accession number per fiscal period, so no amended filings."
      },
      {
        "id": "H-bcfac0",
        "status": "refuted",
        "evidence": ["E-890a02"],
        "why": "Only the concept 'RevenueFromContractWithCustomerExcludingAssessedTax' appears; 'Revenues' concept absent."
      },
      {
        "id": "H-4c3763",
        "status": "supported",
        "evidence": ["E-7abe3b"],
        "why": "Rows exist for FY, Q1, Q2, Q3, showing the count includes both annual and quarterly periods because fiscal_period was not restricted to 'FY'."
      },
      {
        "id": "H-7bc26e",
        "status": "supported",
        "evidence": ["E-bff301"],
        "why": "Within each fiscal period, rows differ by period_frame (NULL vs a value), indicating ingestion duplication."
      }
    ]
  },
  "carryover": {
    "COMPLETED": "All hypotheses tested; H-ab018a and H-bcfac0 refuted; H-4c3763 and H-7bc26e supported.",
    "REMAINING": "",
    "DECISIONS": "The 13 rows are due to combination of annual+quarterly periods and ingestion duplication.",
    "CONTEXT": "Evidence shows 3 FY, 2 Q1, 4 Q2, 4 Q3 rows; duplication visible via period_frame differences."
  }
}
